/**
 * @epicai/chariot — `epic-ai.config.ts` generator for the setup wizard.
 * CHARIOT-SPEC.md:1412 (§17.2 step 7): "write `epic-ai.config.ts`, ...".
 * CHARIOT-SPEC.md:1566 (§20 configuration-file table): "`epic-ai.config.ts`
 * | TypeScript | Per-project federation, autonomy, audit settings."
 * CHARIOT::§17.2::14.
 *
 * MASTER ruling (rulings item 92, 2026-09-04): the generated file exports
 * `Pick<EpicAIConfig, 'federation'|'autonomy'|'audit'>` (the exact three
 * settings §20's own description names), populated from the adapters
 * selected in step 3 and safe runtime defaults; fields the wizard has no
 * basis to populate are OMITTED rather than stubbed with placeholders.
 * Written to `process.cwd()` — a per-PROJECT file, distinct from the
 * per-MACHINE `~/.epic-ai/*` state files (`::15`).
 *
 * Built on the Epic AI® Intelligence Platform
 * Copyright 2026 protectNIL Inc. Elastic-2.0
 */

import * as ts from 'typescript';
import type { AdapterEntry } from '../engine/server/ChariotState.js';

export interface ConfigGeneratorOptions {
  /** AS §1.1 integrity gate — only `npx` is an accepted stdio launcher (`MCPClientAdapter.ts` `INTEGRITY_GATED_STDIO_COMMANDS`). Pass the running package version so generated `npx` entries pin it, matching the MCP-client-registration write path (`setup.ts` `writeMcpConfig` call site). */
  pkgVersion: string;
}

/**
 * Builds one `ServerConnection`-shaped entry per selected adapter that the
 * wizard has enough information to wire up automatically:
 *   - stdio adapters with a known npm `packageName` → launched via the
 *     ONLY integrity-gated stdio command, `npx --no-install <pkg>@<pinned>`
 *     (AS §1.1; mirrors `normalizeAdapter`'s own bridging in
 *     `ChariotState.ts:642-651`).
 *   - streamable-http adapters with a `serverUrl` → `transport:
 *     'streamable-http'`, `url: serverUrl`.
 * Adapters this function can't resolve (REST-only, CLI-only, or missing
 * the fields above) are OMITTED from `servers[]` — never emitted with a
 * guessed/empty command, which would silently fail at connect time.
 */
function buildServerConnections(
  selected: AdapterEntry[],
  opts: ConfigGeneratorOptions,
): Array<Record<string, unknown>> {
  const entries: Array<Record<string, unknown>> = [];
  for (const a of selected) {
    if (a.mcp?.transport === 'stdio' && a.mcp.packageName) {
      entries.push({
        name: a.id,
        transport: 'stdio',
        command: 'npx',
        args: ['--no-install', `${a.mcp.packageName}@${opts.pkgVersion}`],
      });
    }
    // Non-stdio / unresolvable adapters intentionally omitted — see docstring.
  }
  return entries;
}

function jsonLiteral(value: unknown): string {
  return JSON.stringify(value, null, 2);
}

/**
 * CHARIOT::§17.2::14 — renders the TypeScript source text for
 * `epic-ai.config.ts`. Returns a string; the caller is responsible for
 * writing it to `process.cwd()/epic-ai.config.ts` and for running
 * `validateGeneratedConfig()` first.
 */
export function renderConfigFile(
  selectedAdapters: AdapterEntry[],
  opts: ConfigGeneratorOptions,
): string {
  const servers = buildServerConnections(selectedAdapters, opts);
  const federation = { servers };
  // Safest fail-closed default: nothing auto-approved (`AutonomyRules`
  // requires `auto`/`escalate`/`approve` — CHARIOT::§17.2::14 does not
  // pin a default policy, so this wizard scaffolds the empty/manual-review
  // baseline rather than guessing an auto-approve list).
  const autonomy = { tiers: { auto: [] as string[], escalate: [] as string[], approve: [] as string[] } };
  const audit = { store: 'append-only-log' as const, integrity: 'sha256-chain' as const };

  return `// Generated by \`chariot setup\` — CHARIOT::§17.2::14.
// Per-project federation, autonomy, and audit settings
// (CHARIOT-SPEC.md §20 configuration-file table). Safe to hand-edit;
// re-running \`chariot setup\` will NOT overwrite an existing file without
// confirmation.
import type { EpicAIConfig } from '@epicai/chariot';

export const config: Pick<EpicAIConfig, 'federation' | 'autonomy' | 'audit'> = {
  federation: ${jsonLiteral(federation)},
  autonomy: ${jsonLiteral(autonomy)},
  audit: ${jsonLiteral(audit)},
};

export default config;
`;
}

/**
 * Validates the rendered source is syntactically valid TypeScript by
 * running it through the TS compiler's `transpileModule` (per the ruling —
 * a regex/eval sanity check is NOT sufficient). Returns the list of
 * diagnostic messages; an empty array means the file parses cleanly.
 * `transpileModule` performs syntactic transpilation only (no full
 * type-check against `EpicAIConfig`), which is sufficient to catch a
 * malformed adapter id/packageName breaking the generated literal.
 */
export function validateGeneratedConfig(source: string): string[] {
  const result = ts.transpileModule(source, {
    compilerOptions: { module: ts.ModuleKind.ESNext, target: ts.ScriptTarget.ES2022 },
    reportDiagnostics: true,
  });
  return (result.diagnostics ?? []).map((d) =>
    ts.flattenDiagnosticMessageText(d.messageText, '\n'),
  );
}
